import{_ as t,o,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Wrong values and known bugs in older versions","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/04.fehlerbehebung/02.falsche-werte-und-bekannte-fehler.md"},"headers":[],"relativePath":"adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md","filePath":"adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md","lastUpdated":null}'),n={name:"adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md"};function s(i,e,u,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="wrong-values-and-known-bugs-in-older-versions" tabindex="-1">Wrong values and known bugs in older versions <a class="header-anchor" href="#wrong-values-and-known-bugs-in-older-versions" aria-label="Permalink to &quot;Wrong values and known bugs in older versions&quot;">​</a></h1><p><a id="values-costs-far-too-high"></a></p><h2 id="values-or-costs-far-too-high-or-negative-–-is-the-unit-right" tabindex="-1">Values or costs far too high or negative – is the unit right? <a class="header-anchor" href="#values-or-costs-far-too-high-or-negative-–-is-the-unit-right" aria-label="Permalink to &quot;Values or costs far too high or negative – is the unit right?&quot;">​</a></h2><p>Usually a unit doesn&#39;t fit: on the source, on the price or on a start value. Check them in the source&#39;s detail view and then correct the values.</p><table tabindex="0"><thead><tr><th>Wrong</th><th>Result</th><th>Correct</th></tr></thead><tbody><tr><td>unit <code>kWh</code>, device delivers <code>Wh</code></td><td>everything 1,000 times too large</td><td>the unit the device delivers</td></tr><tr><td>meter reading labelled <code>kW</code></td><td>values grow far too fast</td><td>meter reading in <code>kWh</code>, power in <code>W</code></td></tr><tr><td>price in cents, <code>28.5</code> instead of <code>0.285</code></td><td>costs 100 times too high</td><td>price in euros per unit</td></tr><tr><td>start value in <code>Wh</code>, price in <code>kWh</code></td><td>consumption strongly negative</td><td>start value in kWh</td></tr></tbody></table><p>At the top of the detail view is the type, for example &quot;Meter reading · kWh&quot;, and below it the &quot;Total&quot;. Compare it with your meter, then check &quot;Unit&quot; and &quot;Price definition&quot; under &quot;Settings&quot;. The &quot;Problems&quot; tab reports unsuitable start values as &quot;Start value does not fit&quot;.</p><p>Stored values don&#39;t change with the unit. Afterwards, fix the total with &quot;Align meter reading&quot; and recalculate the costs with &quot;Recalculate costs from date&quot;, see <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><p><strong>See also:</strong> <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Which unit on the datapoint?</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Negative values after start values</a></p><p><a id="after-update-restore-values-0"></a></p><h2 id="after-an-update-or-restore-values-are-0-or-sourceanalytix-is-missing" tabindex="-1">After an update or restore, values are 0 or SourceAnalytix is missing <a class="header-anchor" href="#after-an-update-or-restore-values-are-0-or-sourceanalytix-is-missing" aria-label="Permalink to &quot;After an update or restore, values are 0 or SourceAnalytix is missing&quot;">​</a></h2><p>After a restore, the adapter itself is often missing, because a backup saves data, not program code. Reinstall SourceAnalytix from &quot;latest&quot;; the restored instance then keeps running. An update does not change your values.</p><p>After a restore, the total and the settings may come from different points in time:</p><ol><li>Open the source and compare the &quot;Total&quot; with your meter.</li><li>If it doesn&#39;t match, use &quot;Align meter reading&quot;.</li><li>On the &quot;Problems&quot; tab, catch up a &quot;Period rollover missed&quot; with &quot;Recover&quot;.</li></ol><p><strong>See also:</strong> <a href="./../anleitungen/betrieb-und-wartung#data-back-up-move-new">Where is the data?</a></p><p><a id="costs-stay-0-not-calculated"></a></p><h2 id="costs-stay-0-or-are-not-calculated" tabindex="-1">Costs stay 0 or are not calculated <a class="header-anchor" href="#costs-stay-0-or-are-not-calculated" aria-label="Permalink to &quot;Costs stay 0 or are not calculated&quot;">​</a></h2><p>Costs are only created with the &quot;Costs&quot; tick on the source and a valid &quot;Price per unit&quot;. With the cost type &quot;Earnings&quot;, they are under <code>earnings</code>, not <code>costs</code>.</p><ol><li><strong>&quot;Costs&quot; on?</strong> Check it in the detail view under &quot;Settings&quot;.</li><li><strong>Price definition chosen?</strong> Otherwise the &quot;Problems&quot; tab reports it.</li><li><strong>Is the price a number?</strong> Otherwise SourceAnalytix calculates with 0 and logs <code>Price definition &lt;name&gt; has no valid unit price …</code>.</li><li><strong>Price from a datapoint?</strong> If it delivers nothing valid, the &quot;Price per unit&quot; you entered applies; if that is empty, the costs stay 0.</li></ol><p>Afterwards, &quot;Recalculate costs from date&quot; recalculates the costs with the price history.</p><p><strong>See also:</strong> <a href="./../anleitungen/preise-und-kosten#assign-prices-create-custom-tariffs">Assigning prices</a> · <a href="./../anleitungen/quellen-und-einheiten#track-pv-yield-feed-earnings">PV yield and feed-in</a></p><p><a id="huge-consumption-after-power-outage"></a></p><h2 id="huge-consumption-on-power-sources-after-a-power-outage" tabindex="-1">Huge consumption on power sources after a power outage <a class="header-anchor" href="#huge-consumption-on-power-sources-after-a-power-outage" aria-label="Permalink to &quot;Huge consumption on power sources after a power outage&quot;">​</a></h2><p>With power, the last value applies until a new one arrives. If the device fails without reporting 0, the last power is extrapolated over the whole pause. &quot;Maximum gap between power values (minutes)&quot; prevents this.</p><ol><li>Open the power source.</li><li>Under &quot;Settings&quot;, enter a value for &quot;Maximum gap between power values (minutes)&quot; well above the longest normal interval between two values.</li><li>Click &quot;⚡ Apply&quot;. Longer gaps then count as 0.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Leave the field empty if your device only sends on change. Otherwise the consumption of long steady stretches is lost.</p></div><p>If no value arrives for three hours, the &quot;Problems&quot; tab reports &quot;Power source has not reported for a long time&quot;. Repair values already booked as described under <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><p><a id="so-many-decimals"></a></p><h2 id="why-so-many-decimal-places" tabindex="-1">Why so many decimal places? <a class="header-anchor" href="#why-so-many-decimal-places" aria-label="Permalink to &quot;Why so many decimal places?&quot;">​</a></h2><p>The source&#39;s rounding is probably set to <code>-1</code>, meaning unrounded. The default is 3 places for consumption and 2 for costs. Change them in the source&#39;s detail view under &quot;For experts&quot;.</p><p>The values under &quot;Main settings&quot; › &quot;Rounding&quot; only apply to new sources. How many places, zeros or thousands separators you see is also up to your display, such as VIS.</p><p><a id="known-bugs-older-versions-please"></a></p><h2 id="known-bugs-in-older-versions-–-please-update" tabindex="-1">Known bugs in older versions – please update <a class="header-anchor" href="#known-bugs-in-older-versions-–-please-update" aria-label="Permalink to &quot;Known bugs in older versions – please update&quot;">​</a></h2><p>Update to the current version. This documentation only describes that one; which bug was fixed in which version is in the <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/blob/main/README.md#changelog" target="_blank" rel="noreferrer">changelog</a>. Many forum reports, such as duplicated values after a reset or missing day rollovers, concern old versions.</p><p>After updating, the &quot;Problems&quot; tab shows most causes of wrong values directly, with a button to fix them.</p><p><strong>See also:</strong> <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">How do I update SourceAnalytix?</a></p>',35)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
